#!/usr/bin/env ruby
require 'json';require 'fileutils';root=File.expand_path('..',__dir__);files=Dir.glob(File.join(root,'server/**/*.java'));entries=[];forbidden=[]
files.each do|p|;t=File.binread(p).encode('UTF-8',invalid: :replace,undef: :replace,replace: '');next unless t.include?('@Transactional');t.scan(/@Transactional(?:\(([^)]*)\))?/m).each do|m|;args=m[0].to_s;prop=args[/propagation\s*=\s*Propagation\.([A-Z_]+)/,1]||'REQUIRED';entry={'file'=>p.delete_prefix(root+'/'),'propagation'=>prop,'arguments'=>args.gsub(/\s+/,' ').strip};entries<<entry;forbidden<<entry if %w[NESTED NOT_SUPPORTED NEVER SUPPORTS].include?(prop);end;end
policy=File.read(File.join(root,'docs/事务传播策略.md'));checks={'inventory_created'=>!entries.empty?,'business_policy_documented'=>policy.include?('REQUIRED')&&policy.include?('REQUIRES_NEW'),'no_unsafe_propagation'=>forbidden.empty?,'jdbc_boundary_declared'=>policy.include?('JdbcTransactionBoundary')};result={'task'=>'JAVA04','passed'=>checks.values.all?,'checks'=>checks,'annotations'=>entries,'forbidden'=>forbidden};p=File.join(root,'work/audit/transaction-propagation.json');FileUtils.mkdir_p(File.dirname(p));File.write(p,JSON.pretty_generate(result)+"\n");puts JSON.generate(result);exit(result['passed'] ? 0 : 1)
